=== ValidateRemind
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: who reminds the claim (a blank name is refused). */
public class ValidateRemind {
    public void validate(@RequestBody RemindRequest request, Out<ClaimReminder> reminder)
            throws InvalidClaimStatusException {
        String by = request == null || request.by() == null ? "" : request.by().trim();
        if (by.isEmpty()) {
            throw new InvalidClaimStatusException("Who reminds the claim is required");
        }
        reminder.set(new ClaimReminder(by));
    }
}
=== RemindRequest
package net.officefloor.hq.app.claim;

/** Body of reminding a claim: who reminds it. */
public record RemindRequest(String by) {
}
=== LoadClaim
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads a claim of the sheet by id; one not on the sheet is a 404. */
public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") String claimId,
            ClaimRepository claims, Out<Claim> claim) throws ClaimNotFoundException {
        Claim found;
        try {
            found = claims.find(sheetId.trim(), Long.parseLong(claimId.trim()));
        } catch (NumberFormatException e) {
            found = null;
        }
        if (found == null) {
            throw new ClaimNotFoundException("No claim " + claimId);
        }
        claim.set(found);
    }
}
=== SaveReminder
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Stores a reminder on the sheet's today, but only while the claim is OPEN or PENDING and not yet reminded that day. */
public class SaveReminder {
    public void save(@Val Claim claim, ClaimRepository claims, SheetRepository sheets)
            throws InvalidClaimStatusException {
        if (claim.status() != ClaimStatus.OPEN && claim.status() != ClaimStatus.PENDING) {
            throw new InvalidClaimStatusException("Only an OPEN or PENDING claim can be reminded");
        }
        if (!claims.remind(claim, sheets.today(claim.sheetId()))) {
            throw new InvalidClaimStatusException("The claim was already reminded today");
        }
    }
}
